import{_ as s,o as a,c as i,ai as t}from"./chunks/framework.Ci0kozOl.js";const o="/assets/3.0/images/association-types.png",k=JSON.parse('{"title":"Configurable Associations","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/packages/configurable-associations.md","filePath":"3.0/packages/configurable-associations.md","lastUpdated":1785947307000}'),n={name:"3.0/packages/configurable-associations.md"};function d(c,e,l,r,p,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="configurable-associations" tabindex="-1">Configurable Associations <a class="header-anchor" href="#configurable-associations" aria-label="Permalink to &quot;Configurable Associations&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Product associations let you link products to one another — a camera to its lenses, a jacket to the trousers that complete the outfit. UnoPim ships with three built-in association types: <em>Related Products</em>, <em>Up Sells</em>, and <em>Cross Sells</em>. Starting with UnoPim 3.0, you are no longer limited to these three: you may define your own association types, each with localized names and custom per-link fields.</p><p>Sometimes you may wish to capture more than the link itself. For example, a &quot;spare parts&quot; association might need a per-link quantity, or a &quot;replaced by&quot; association might need a localized note explaining the replacement. Configurable associations make both possible without touching a line of schema.</p><p>The feature lives in the <strong><code>Webkul\\Product</code></strong> package (schema, models, repositories, validators), with its admin UI in <code>Webkul\\Admin</code> and import/export jobs in <code>Webkul\\DataTransfer</code>.</p><p><img src="'+o+`" alt="Association types in the UnoPim admin"></p><h2 id="defining-association-types" tabindex="-1">Defining Association Types <a class="header-anchor" href="#defining-association-types" aria-label="Permalink to &quot;Defining Association Types&quot;">​</a></h2><p>You may manage association types from the admin panel under <strong>Catalog → Association Types</strong>. Each type has a unique code, localized names, a status, and a position that controls its ordering in the product form.</p><p>The seeder creates the three default types — <code>related_products</code>, <code>up_sells</code>, and <code>cross_sells</code> — with <code>is_user_defined = 0</code>, and the controller protects them from accidental changes:</p><ul><li><code>store()</code> forces <code>is_user_defined = 1</code>, so only the seeder may create defaults.</li><li><code>destroy()</code> returns HTTP 400 for a non-user-defined type, while <code>massDestroy()</code> silently skips them.</li><li><code>update()</code> strips <code>code</code> and <code>is_user_defined</code> from the payload — both are immutable on every type.</li></ul><h2 id="custom-link-fields" tabindex="-1">Custom Link Fields <a class="header-anchor" href="#custom-link-fields" aria-label="Permalink to &quot;Custom Link Fields&quot;">​</a></h2><p>You may attach custom fields to any association type; the values are captured per link when a user edits a product&#39;s associations. Field definitions hang off the type in <code>association_type_fields</code>, and the allowed field types come from the <code>association_field_types</code> config file (<code>packages/Webkul/Product/src/Config/association_field_types.php</code>) — currently <strong><code>text</code></strong> and <strong><code>boolean</code></strong>. The storage, validation, and rendering layers already understand richer types, which is why this config file is the single place to widen the list.</p><p>Per-link values are stored in the <code>additional_data</code> JSON column of <code>product_associations</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;common&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:          { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;&lt;field_code&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;locale_specific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;en_US&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;&lt;field_code&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A field with <code>value_per_locale = 1</code> reads and writes the <code>locale_specific.&lt;locale&gt;</code> bucket, as resolved by <code>AssociationTypeField::getJsonPath()</code>; otherwise the value lives in <code>common</code>.</p><p>Before any link is persisted, its custom-field data is validated by the association validator:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Webkul\\Product\\Validator\\AssociationValidator</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $typeId, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $additionalData);</span></span></code></pre></div><p>Unknown field codes are rejected, and each field type contributes its own rules — booleans via <code>BooleanString</code>, dates via <code>date_format</code>, and options via <code>FieldOption</code>.</p><h2 id="retrieving-and-syncing-links" tabindex="-1">Retrieving and Syncing Links <a class="header-anchor" href="#retrieving-and-syncing-links" aria-label="Permalink to &quot;Retrieving and Syncing Links&quot;">​</a></h2><p>When working with associations in code, you should go through the repositories rather than querying tables directly:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Webkul\\Product\\Repositories\\AssociationTypeRepository</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Webkul\\Product\\Repositories\\ProductAssociationRepository</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>To retrieve the enabled types ordered by position — with translations, fields, and options eager-loaded — call <code>AssociationTypeRepository::getActiveTypes()</code>. A single type may be looked up with <code>findByCode(string $code)</code>.</p><p>For links themselves, <code>ProductAssociationRepository::getLinksForProduct(int $productId)</code> returns all of a product&#39;s links with the type and related product eager-loaded. To replace a type&#39;s links transactionally, use <code>syncType()</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$associationRepository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($productId, $typeId, [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;related_product_id&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;position&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;additional_data&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p>The link shape everywhere is <code>[&#39;related_product_id&#39; =&gt; int, &#39;position&#39; =&gt; ?int, &#39;additional_data&#39; =&gt; ?array]</code>. <code>syncType()</code> fires the sync events, while the single-row <code>upsertLink()</code> / <code>deleteLink()</code> methods used by imports intentionally fire <strong>no</strong> events.</p><p>Type updates resolve field rows <strong>by code</strong> rather than by the browser&#39;s <code>isNew</code> flag, so a resubmitted form stays idempotent.</p><h2 id="legacy-json-compatibility" tabindex="-1">Legacy JSON Compatibility <a class="header-anchor" href="#legacy-json-compatibility" aria-label="Permalink to &quot;Legacy JSON Compatibility&quot;">​</a></h2><p>Before 3.0, associations lived as SKU lists inside <code>products.values[&#39;associations&#39;]</code>. That shape still works — <code>Webkul\\Product\\Type\\AbstractType</code> keeps both stores in sync:</p><ul><li><code>syncAssociationLinks()</code> mirrors the legacy JSON SKU lists into <code>product_associations</code> on every product save, with <code>preserveAdditionalData: true</code>, so a plain save never wipes custom field values.</li><li><code>prepareRichAssociations()</code> / <code>syncRichAssociations()</code> handle the rich UI/API payload: validation happens <strong>before</strong> the product saves, and syncing happens after, per type, with the payload authoritative.</li><li>A one-time migration (<code>backfill_product_associations</code>) streamed existing catalogs into the new table using chunked <code>insertOrIgnore</code> — idempotent and non-destructive.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Extensions should read associations from <code>product_associations</code> (or the product API&#39;s <code>associations</code> block), not from the raw JSON. The JSON mirror only covers the three legacy sections.</p></div><h2 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h2><p>There is no dedicated association endpoint. Instead, associations ride on the <strong>product</strong> endpoints:</p><ul><li><strong>Read</strong> — single-product GET responses include an <code>associations</code> block grouped by type code, each entry shaped as <code>{&quot;related_sku&quot;: ..., &quot;additional_data&quot;: {...}}</code>. The legacy <code>values.associations.&lt;section&gt;</code> output is unchanged.</li><li><strong>Write</strong> — product create and update payloads accept the same <code>associations</code> structure; the controllers validate custom-field data before persisting and sync after.</li></ul><h2 id="import-and-export" tabindex="-1">Import and Export <a class="header-anchor" href="#import-and-export" aria-label="Permalink to &quot;Import and Export&quot;">​</a></h2><p>Both jobs use the type key <strong><code>product-associations</code></strong>. Import rows carry <code>sku</code>, <code>association_type</code>, <code>related_sku</code>, plus one column per active field code, and delete mode is supported via the sample variants. The importer uses <code>upsertLink</code> / <code>deleteLink</code>, so it accumulates links and never prunes ones it did not touch. The export job streams from <code>ProductAssociationRepository</code> to CSV, XLS, or XLSX.</p><p>Regular product imports and exports also carry the legacy association sections.</p><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><p>For reference, the underlying tables are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>association_types                         code (unique), status, position, is_user_defined</span></span>
<span class="line"><span>association_type_translations             name per locale</span></span>
<span class="line"><span>association_type_fields                   code, type, validation, position, is_required,</span></span>
<span class="line"><span>                                          is_unique, status, section, value_per_locale,</span></span>
<span class="line"><span>                                          enable_wysiwyg, regex_pattern</span></span>
<span class="line"><span>association_type_field_translations       name per locale</span></span>
<span class="line"><span>association_type_field_options            code, sort_order</span></span>
<span class="line"><span>association_type_field_option_translations  label per locale</span></span>
<span class="line"><span></span></span>
<span class="line"><span>product_associations                      product_id, association_type_id,</span></span>
<span class="line"><span>                                          related_product_id, position,</span></span>
<span class="line"><span>                                          additional_data (json)</span></span></code></pre></div><p>A link is unique per <code>(product_id, association_type_id, related_product_id)</code>. Both product foreign keys cascade, so deleting a product removes its links in both directions.</p><h2 id="admin-routes-and-validation" tabindex="-1">Admin Routes and Validation <a class="header-anchor" href="#admin-routes-and-validation" aria-label="Permalink to &quot;Admin Routes and Validation&quot;">​</a></h2><p>Routes live under <code>admin/catalog/association-types</code> (<code>admin.catalog.association_types.*</code>): index, search, store, edit, update, delete, mass-delete, and mass-update. ACL keys are <code>catalog.association_types</code> plus <code>.create</code>, <code>.edit</code>, <code>.delete</code>, <code>.mass_update</code>, and <code>.mass_delete</code>.</p><p>Validation is handled by <code>Webkul\\Admin\\Http\\Requests\\AssociationTypeRequest</code> — type codes must pass <code>Webkul\\Core\\Rules\\Code</code>, reserved field codes (<code>code</code>, <code>type</code>, <code>locale</code>) are rejected, and duplicate field codes within a type fail with a dedicated message.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>UnoPim will automatically fire the following events, which you may listen for in your own packages:</p><table tabindex="0"><thead><tr><th>Event</th><th>Fired</th></tr></thead><tbody><tr><td><code>catalog.association_type.create.before</code> / <code>.after</code></td><td>Type creation</td></tr><tr><td><code>catalog.association_type.update.before</code> / <code>.after</code></td><td>Type update and mass update</td></tr><tr><td><code>catalog.association_type.delete.before</code> / <code>.after</code></td><td>Type delete and mass delete</td></tr><tr><td><code>product_association.sync.before</code> / <code>.after</code></td><td>Every link sync (<code>[$productId, $typeId, $links]</code>)</td></tr></tbody></table><p>Types and their fields are audited through <code>HistoryTrait</code> under the <code>association_type</code> history tag.</p>`,47)])])}const y=s(n,[["render",d]]);export{k as __pageData,y as default};
